@font-face{font-family:Orbitron;src:url('./assets/fonts/orbitron.woff2')}@font-face{font-family:Rajdhani;src:url('./assets/fonts/rajdhani.woff2');font-weight:500 700}*{box-sizing:border-box} :root{--cyan:#73f5ff;--lime:#d8ff64;--white:#f4f8ff;--muted:#91a4ba;--panel:rgba(7,15,28,.72)}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#07101e;color:var(--white);font-family:Rajdhani,Arial,sans-serif;touch-action:none}button,a{-webkit-tap-highlight-color:transparent}#game{position:relative;width:100%;height:100%;min-height:100svh;overflow:hidden;background:radial-gradient(ellipse at 50% 30%,#18304b 0%,#0b172a 46%,#060b15 100%);isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:0}.vignette{position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,rgba(4,9,18,.62),transparent 25%,transparent 55%,rgba(5,9,17,.63)),radial-gradient(ellipse at center,transparent 35%,rgba(4,8,15,.42) 100%)}.topbar{position:absolute;z-index:3;left:0;right:0;top:0;padding:max(20px,env(safe-area-inset-top)) 4.2vw 0;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:10px;align-items:center;color:#fff;text-decoration:none;font:700 15px Orbitron,sans-serif;letter-spacing:3px}.brand-mark{width:27px;height:27px;border:1px solid rgba(115,245,255,.55);display:grid;place-items:center;transform:skew(-10deg);color:var(--cyan);font-size:13px;box-shadow:0 0 16px #36dff033}.brand-dot{color:var(--cyan)}.top-right{display:flex;gap:9px;align-items:center;font:700 9px Orbitron,sans-serif;letter-spacing:1.6px;color:#b5c5d6}.live-dot{height:6px;width:6px;border-radius:50%;background:#c9ff5b;box-shadow:0 0 10px #d8ff64}.sound-button{margin-left:9px;border:1px solid #ffffff3b;background:#101b2c88;color:#d4e5f4;border-radius:50%;width:32px;height:32px;font-size:16px;cursor:pointer}.hud{position:absolute;z-index:3;left:4.2vw;right:4.2vw;top:91px;display:flex;align-items:flex-start;gap:32px;pointer-events:none;transition:opacity .25s}.hud-label{font:700 8px Orbitron,sans-serif;letter-spacing:1.6px;color:#a6bacf}.score-line{font:700 30px Orbitron,sans-serif;letter-spacing:-1px;line-height:1.1;text-shadow:0 0 20px #73f5ff44}.unit{font:600 12px Rajdhani,sans-serif;color:var(--cyan);margin-left:5px;letter-spacing:1px}.energy-block{width:min(190px,24vw);padding-top:2px}.energy-head{display:flex;justify-content:space-between;margin-bottom:8px}.energy-head span:last-child{font:700 10px Orbitron,sans-serif;color:var(--lime)}.energy-track{height:5px;background:#dcecff24;position:relative;overflow:hidden;border-radius:5px}.energy-track div{height:100%;width:0;background:linear-gradient(90deg,#63e6f4,#d8ff64);border-radius:5px;box-shadow:0 0 12px #9bff66;transition:width .18s}.charge-glint{position:absolute;right:0;top:0;height:100%;width:10px;background:#fff;filter:blur(4px);opacity:.7}.coin-count{margin-left:auto;border:1px solid #9deff040;background:#08152577;padding:7px 12px;border-radius:4px;display:flex;gap:8px;align-items:center;font:700 15px Orbitron,sans-serif}.coin-icon{color:var(--lime);font-size:16px;text-shadow:0 0 14px #c5ff50}.speed-indicator{position:absolute;z-index:3;right:4.2vw;bottom:15%;display:flex;align-items:baseline;gap:4px;color:#eaf9ff;font:700 25px Orbitron,sans-serif;text-shadow:0 0 20px #77efff66;transition:transform .2s}.speed-indicator small{font:700 8px Orbitron,sans-serif;color:#9eb2c7;letter-spacing:1.5px}.speed-line{width:18px;height:2px;background:var(--cyan);display:inline-block;margin-right:2px;box-shadow:0 0 9px var(--cyan)}.power-tip{position:absolute;z-index:3;right:4.2vw;bottom:calc(15% + 37px);font:700 9px Orbitron,sans-serif;letter-spacing:1.2px;color:var(--lime);opacity:0;transform:translateY(5px);transition:.25s;pointer-events:none}.power-tip.ready{opacity:1;transform:none}.tip-icon{margin-right:5px}.screen{position:absolute;inset:0;z-index:4}.intro-screen{pointer-events:none}.intro-copy{position:absolute;left:11.5vw;top:50%;transform:translateY(-42%);width:min(480px,47vw);pointer-events:auto}.eyebrow{display:flex;align-items:center;gap:10px;font:700 9px Orbitron,sans-serif;letter-spacing:2.1px;color:var(--cyan);margin-bottom:17px}.eyebrow-line{width:28px;height:1px;background:var(--cyan);box-shadow:0 0 7px var(--cyan)}h1,h2{font:900 clamp(54px,8.5vw,110px)/.84 Orbitron,sans-serif;letter-spacing:-.075em;margin:0;color:#f5f8ff;text-shadow:0 5px 40px #dff6ff1a}h1 span,h2 span{color:transparent;-webkit-text-stroke:1px rgba(222,239,255,.72);text-shadow:none}h1 i{font-style:normal;color:var(--cyan);text-shadow:0 0 35px #65e9ffad}.intro-desc{font-size:19px;line-height:1.25;color:#b4c6d9;margin:21px 0 22px;font-weight:600;letter-spacing:.25px}.primary-button{position:relative;display:flex;align-items:center;justify-content:space-between;gap:40px;padding:0 18px;height:48px;min-width:177px;border:0;border-radius:2px;background:var(--lime);color:#101825;font:700 10px Orbitron,sans-serif;letter-spacing:1.5px;cursor:pointer;box-shadow:0 0 25px #caff4a28;transition:transform .16s,box-shadow .16s}.primary-button:hover{transform:translateY(-2px);box-shadow:0 0 35px #caff4a50}.button-arrow{font:700 21px Rajdhani,sans-serif}.control-hint{margin-top:24px;display:flex;align-items:center;gap:6px;color:#98acc1}.keycap{border:1px solid #c7d9ec45;background:#0b152477;min-width:23px;height:22px;display:grid;place-items:center;border-radius:3px;font:700 11px Rajdhani,sans-serif;color:#dbe8f5;padding:0 5px}.hint-text{font:700 8px Orbitron,sans-serif;letter-spacing:1px;margin:0 5px}.hint-divider{color:#4d6279;margin:0 3px}.hero-caption{position:absolute;right:5vw;bottom:8.5%;display:flex;align-items:center;gap:10px;font:700 8px Orbitron,sans-serif;letter-spacing:1.8px;color:#c5d5e5}.caption-line{width:30px;height:1px;background:var(--cyan);box-shadow:0 0 6px var(--cyan)}.intro-coordinates{position:absolute;right:5vw;top:49%;writing-mode:vertical-rl;font:700 8px Orbitron,sans-serif;letter-spacing:2px;color:#c2d3e2aa}.gameover-screen{display:grid;place-items:center;background:rgba(5,10,19,.52);backdrop-filter:blur(7px);pointer-events:auto}.gameover-card{width:min(390px,88vw);padding:30px 35px 32px;border:1px solid #b8d7e52e;background:linear-gradient(145deg,#102034eF,#091321f2);box-shadow:0 25px 100px #020711aa;animation:card-in .4s ease-out}.gameover-card h2{font-size:45px;line-height:.95;letter-spacing:-.07em;margin-bottom:20px}.gameover-card h2 span{-webkit-text-stroke-width:1px}.run-label{margin:0;color:#98afc4;font:700 8px Orbitron,sans-serif;letter-spacing:1.7px}.final-distance{font:700 56px/.95 Orbitron,sans-serif;color:#fff;margin:6px 0 17px;text-shadow:0 0 22px #73f5ff44}.final-distance small{font:700 13px Orbitron,sans-serif;color:var(--cyan);margin-left:7px}.run-stats{display:flex;border-top:1px solid #c8dcec22;border-bottom:1px solid #c8dcec22;padding:12px 0;margin-bottom:21px;gap:35px}.run-stats div{display:grid;grid-template-columns:18px auto;grid-template-rows:auto auto;column-gap:5px;align-items:center}.run-stats .stat-icon{grid-row:1/3;color:var(--lime);font-size:15px}.run-stats b{font:700 15px Orbitron,sans-serif}.run-stats small{font:700 7px Orbitron,sans-serif;color:#91a4ba;letter-spacing:1px}.gameover-card .primary-button{width:100%}.hidden{display:none!important}.toast{position:absolute;z-index:5;top:29%;left:50%;transform:translate(-50%,-10px);font:700 12px Orbitron,sans-serif;letter-spacing:2px;padding:11px 18px;background:#d8ff64;color:#101825;box-shadow:0 0 35px #d8ff6477;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.flash{position:absolute;z-index:2;inset:0;pointer-events:none;background:#d8ff64;opacity:0}.flash.pulse{animation:flash .4s ease-out}.touch-controls{position:absolute;z-index:5;left:0;right:0;bottom:max(21px,env(safe-area-inset-bottom));display:flex;align-items:end;justify-content:space-between;padding:0 5vw;pointer-events:none;opacity:0;transition:opacity .2s}.touch-controls.active{opacity:1}.touch-btn{pointer-events:auto;touch-action:none;border:1px solid #c6e8ed52;background:rgba(8,19,33,.52);backdrop-filter:blur(8px);color:#eafaff;display:grid;place-items:center;cursor:pointer;user-select:none;transition:background .12s,transform .12s;box-shadow:0 5px 20px #02081244}.touch-btn:active{background:#75eaf363;transform:scale(.94)}.dodge-left,.dodge-right{height:53px;width:53px;border-radius:50%;font:400 36px/1 Rajdhani,sans-serif}.touch-right{display:flex;gap:9px;align-items:end}.action-btn,.boost-btn{height:54px;width:54px;border-radius:50%;gap:0;align-content:center}.action-btn .action-icon,.boost-btn .action-icon{font:700 17px Rajdhani,sans-serif;line-height:19px}.action-btn small,.boost-btn small{font:700 6px Orbitron,sans-serif;letter-spacing:.6px;color:#b9c9d7}.boost-btn{border-color:#d8ff6466;color:var(--lime)}.boost-btn .action-icon{font-size:15px}.mobile-note{position:absolute;z-index:3;left:50%;transform:translateX(-50%);bottom:calc(max(21px,env(safe-area-inset-bottom)) + 68px);font:700 7px Orbitron,sans-serif;letter-spacing:1.2px;color:#bbcedeaa;white-space:nowrap;display:none}.pause-badge{position:absolute;z-index:4;top:50%;left:50%;transform:translate(-50%,-50%);background:#091523d9;border:1px solid #c7e9ef55;padding:14px 19px;font:700 9px Orbitron,sans-serif;letter-spacing:1.5px}.pause-badge span{color:var(--lime);padding:0 5px}@keyframes flash{0%{opacity:.32}100%{opacity:0}}@keyframes card-in{from{transform:translateY(12px);opacity:0}to{transform:none;opacity:1}}
@media(max-width:700px){.topbar{padding: max(16px,env(safe-area-inset-top)) 20px 0}.brand{font-size:12px;letter-spacing:2px}.brand-mark{width:24px;height:24px}.top-right{font-size:7px;letter-spacing:1px}.sound-button{width:30px;height:30px;margin-left:4px}.hud{top:73px;left:20px;right:20px;gap:15px}.score-line{font-size:24px}.hud-label{font-size:7px;letter-spacing:1.2px}.energy-block{width:min(145px,36vw);padding-top:1px}.coin-count{padding:6px 9px;font-size:12px;gap:6px}.energy-head{margin-bottom:7px}.intro-copy{left:8vw;top:43%;transform:translateY(-35%);width:84vw}.eyebrow{font-size:8px;margin-bottom:17px}h1{font-size:clamp(57px,15vw,86px)}.intro-desc{font-size:17px;margin:17px 0 19px}.primary-button{height:46px;min-width:166px}.control-hint{margin-top:18px;gap:4px}.hint-text{font-size:7px;margin:0 3px}.keycap{height:20px;min-width:21px}.hero-caption{right:7vw;bottom:calc(max(21px,env(safe-area-inset-bottom)) + 115px);font-size:7px}.intro-coordinates{right:5vw;top:42%;font-size:7px}.touch-controls{padding:0 20px}.touch-controls.active{opacity:1}.mobile-note{display:block}.speed-indicator{right:21px;bottom:22%;font-size:18px}.speed-indicator small{font-size:7px}.power-tip{right:20px;bottom:calc(22% + 29px);font-size:8px}.gameover-card{padding:25px 26px}.gameover-card h2{font-size:41px}}
@media(min-width:701px){.touch-controls.active{opacity:0;pointer-events:none}.mobile-note{display:none}}
@media(max-height:650px) and (max-width:700px){.intro-copy{top:45%;transform:translateY(-40%)}h1{font-size:57px}.intro-desc{margin:12px 0 14px;font-size:15px}.control-hint{margin-top:12px}.hero-caption{display:none}.touch-btn{height:47px;width:47px}.touch-controls{bottom:12px}}

import * as THREE from './vendor/three.module.js';

const canvas = document.querySelector('#scene');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.7));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.17;

const scene = new THREE.Scene();
scene.background = new THREE.Color('#091323');
scene.fog = new THREE.FogExp2('#101d32', 0.0095);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, 0.1, 180);
camera.position.set(0, 5.2, 10.4);
camera.lookAt(0, 1.3, -9);
scene.add(new THREE.HemisphereLight(0x9cc9e6, 0x182338, 1.65));
const moonLight = new THREE.DirectionalLight(0xbde9ff, 2.2); moonLight.position.set(-5, 12, 8); scene.add(moonLight);
const cityGlow = new THREE.PointLight(0x1ba9c9, 22, 38, 1.8); cityGlow.position.set(0, 7, -16); scene.add(cityGlow);
const pinkGlow = new THREE.PointLight(0x923baf, 16, 28, 2); pinkGlow.position.set(9, 5, -25); scene.add(pinkGlow);

const mat = (color, roughness=.72, metalness=.05, emissive=0x000000, intensity=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness, emissive, emissiveIntensity:intensity });
const roadMat=mat('#111a2a',.91), sidewalkMat=mat('#273247'), darkMat=mat('#101a2a'), windowBlue=mat('#25445b',.36,.2,0x1c7193,.65), windowPink=mat('#5d2a61',.38,.1,0x9a3a99,.8), windowGold=mat('#705534',.4,.1,0xffbb55,.7), cyanMat=mat('#49e7f2',.3,.25,0x33ddee,2.2), limeMat=mat('#d8ff64',.3,.1,0xb6f94f,1.8), redMat=mat('#f06478',.3,.1,0xc72842,1.2);
const boxGeo=new THREE.BoxGeometry(1,1,1);
function cube(parent, material, x,y,z,sx,sy,sz){const m=new THREE.Mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=false;m.receiveShadow=false;parent.add(m);return m;}

// Roadway, luminous lane guides, and a loop of passing street details.
cube(scene,roadMat,0,-.34,-46,13,.55,120);
cube(scene,sidewalkMat,-7.2,-.12,-46,1.5,.75,120); cube(scene,sidewalkMat,7.2,-.12,-46,1.5,.75,120);
for (const x of [-4.25,4.25]) cube(scene,cyanMat,x,.035,-46,.055,.035,120);
cube(scene,mat('#101b2c'),0,-.7,-46,120,.35,125);
const laneDash=[];
for(let lane=0;lane<2;lane++) for(let i=0;i<18;i++) {let d=cube(scene,mat('#6a8b9b',.5,.1,0x224357,.35),lane===0?-1.35:1.35,.002,-93+i*6,.045,.018,2.2);laneDash.push(d);}

// Procedural block-by-block city with lit windows and rooftop neon.
const buildings=[];
function makeBuilding(side,index){
  const g=new THREE.Group(); const width=3.6+Math.random()*4.2, height=9+Math.random()*20, depth=8+Math.random()*9;
  const x=side*(8.4+width*.48+Math.random()*2.2); g.position.set(x,0,-10-index*15-Math.random()*8); g.userData={side,width,height,depth};
  const baseColor=['#18263a','#1a2636','#202638','#172333','#20283a'][Math.floor(Math.random()*5)];
  cube(g,mat(baseColor,.88),0,height/2,0,width,height,depth);
  cube(g,mat('#26364b',.6,.15),0,height+.13,0,width+.3,.26,depth+.3);
  const winMaterials=[windowBlue,windowPink,windowGold];
  const cols=Math.max(2,Math.floor(width/1.12)), rows=Math.floor(height/1.5);
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){
    if(Math.random()<.22)continue;
    const wm=winMaterials[(Math.random()*winMaterials.length)|0];
    const wx=-width/2+.42+c*(width-.84)/Math.max(1,cols-1), wy=1+r*1.35;
    cube(g,wm,wx,wy,depth/2+.014,.42,.68,.035);
  }
  // side-face windows
  for(let r=0;r<rows;r++)for(let c=0;c<2;c++)if(Math.random()>.3)cube(g,winMaterials[(Math.random()*3)|0],side*(width/2+.014),1.2+r*1.5,-depth*.25+c*depth*.5,.035,.68,.55);
  const signMat=side===1?windowPink:windowBlue;
  if(index%3!==1){cube(g,signMat,0,height*.72,depth/2+.05,width*.53,.7,.08);cube(g,mat('#d8f7ff',.4,.05,side===1?0xec53da:0x50eaff,2.8),0,height*.72,depth/2+.1,width*.39,.055,.025);}
  if(index%4===0)cube(g,cyanMat,0,height+1.1,0,.07,2,.07);
  scene.add(g);buildings.push(g);
}
for(let side of [-1,1])for(let i=0;i<11;i++)makeBuilding(side,i);

// Hazy skyline, moon and stars.
const starGeo=new THREE.BufferGeometry(), starPoints=[];
for(let i=0;i<160;i++)starPoints.push((Math.random()-.5)*140,8+Math.random()*40,-65-Math.random()*70);
starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPoints,3));
scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xb4e9ff,size:.14,transparent:true,opacity:.72,sizeAttenuation:true})));
const moon=new THREE.Mesh(new THREE.SphereGeometry(2.1,20,20),new THREE.MeshBasicMaterial({color:0x9ed4e3,transparent:true,opacity:.72}));moon.position.set(-24,29,-90);scene.add(moon);
const halo=new THREE.Mesh(new THREE.SphereGeometry(3.1,20,20),new THREE.MeshBasicMaterial({color:0x35aac4,transparent:true,opacity:.08,side:THREE.BackSide}));halo.position.copy(moon.position);scene.add(halo);

