 for(let i=shards.length-1;i>=0;i--){const s=shards[i];s.position.z+=worldSpeed*dt;s.rotation.y+=dt*2.5;s.rotation.z+=dt*.7;if(Math.abs(s.position.z-1.35)<1.4&&Math.abs(hero.position.x-s.position.x)<1.35){coins++;charge=Math.min(100,charge+13);coinEl.textContent=coins;playTone(660+coins%4*80,.08);scene.remove(s);shards.splice(i,1);continue;}if(s.position.z>11){scene.remove(s);shards.splice(i,1);}}
