function pauseGame(){
  if(state==='running'){state='paused';$('#pauseBadge').classList.remove('hidden');updateControls();}
  else if(state==='paused'){state='running';$('#pauseBadge').classList.add('hidden');updateControls();lastTime=performance.now();}
}
